// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;
    function setUp() public { c = new MONEY_BOX(); }

    function testFuzz_property(uint256 initVal, uint256 newVal, address actor) public {
        vm.assume(actor != address(0));
        // set the initial minimum sum before initialization
        vm.prank(actor);
        c.SetMinSum(initVal);

        // initialize the contract
        c.Initialized();

        // after initialization, SetMinSum must have no effect
        vm.prank(actor);
        try c.SetMinSum(newVal) { } catch { }

        assertTrue(c.MinSum() == initVal);
    }
}
